INSERT INTO `review` VALUES (1,1,2,NULL,5,'手机非常好用，钛金属手感很棒，系统流畅！',NULL,'感谢您的支持！欢迎再次购买。','2024-01-15 14:30:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(2,1,3,NULL,4,'手机不错，但是价格有点贵，希望多搞活动',NULL,'我们会考虑您的建议，请关注我们的活动。','2024-01-16 10:20:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(3,1,5,NULL,5,'拍照效果太棒了，特别是夜景模式',NULL,'感谢好评！祝您使用愉快。','2024-01-17 09:15:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(4,2,3,NULL,5,'华为手机越来越好了，支持国货！',NULL,'感谢您的支持，华为因您而精彩！','2024-01-14 16:45:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(5,6,4,NULL,5,'M3芯片性能强劲，续航超级给力',NULL,'感谢您对Apple产品的认可！','2024-01-13 11:30:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(6,11,2,NULL,5,'降噪效果惊艳，音质也很好',NULL,NULL,NULL,0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(7,17,3,NULL,4,'鞋子很帅，就是有点硬，需要适应一下',NULL,'Air Jordan 1需要一定时间的穿着适应，感谢您的反馈。','2024-01-12 15:20:00',0,1,'2026-04-15 18:19:27','2026-04-15 18:19:27'),(8,17,4,NULL,5,'经典鞋款，百搭神器',NULL,NULL,NULL,1,1,'2026-04-15 18:19:27','2026-04-15 18:19:27');
